// @generated by project-forge — visual-layout-charts.mjs (lifecycle, dataflow, timeline, waterfall clean-room layout engines)

import {
  expandLayoutBounds,
  kahnTopoSort,
  normalizeOrthogonalPoints,
  roundCoord,
  routeEdgesOrthogonal,
  roundedOrthogonalPath,
  spreadSidePorts,
  truncateLabel,
} from './visual-router.mjs'

export const QUIET_GAP_RATIO = 4

function findLongestAcyclicSpine(states, transitions) {
  const adj = new Map(states.map((s) => [s, []])), indeg = new Map(states.map((s) => [s, 0]))
  for (const t of transitions) {
    if (!adj.has(t.from) || !adj.has(t.to) || t.from === t.to || adj.get(t.from).includes(t.to)) continue
    adj.get(t.from).push(t.to); indeg.set(t.to, (indeg.get(t.to) || 0) + 1)
  }
  for (const list of adj.values()) list.sort()

  const starts = [...states].sort((a, b) => ((indeg.get(a) || 0) - (indeg.get(b) || 0)) || a.localeCompare(b))
  let best = [], budget = 2000
  const dfs = (cur, path, seen) => {
    if (budget <= 0) return
    budget -= 1
    if (path.length > best.length) best = [...path]
    if (path.length >= 16) return
    for (const nxt of adj.get(cur) || []) {
      if (seen.has(nxt)) continue
      seen.add(nxt); path.push(nxt); dfs(nxt, path, seen); path.pop(); seen.delete(nxt)
    }
  }
  for (const s of starts) { if (budget <= 0) break; dfs(s, [s], new Set([s])) }
  return best.length > 0 ? best : states.slice(0, 1)
}

/** Lifecycle 状态生命周期布局：提取最长无环主路径为水平主干脊柱，回退/跨跳走顶部跳弧，分支状态落底行。 */
export function layoutLifecycleDiagram(evidence, {
  nodeW = 144, nodeH = 54, gapX = 56, branchGapY = 82, arcStep = 26, pad = 40,
} = {}) {
  const transitions = Array.isArray(evidence?.transitions) ? evidence.transitions : []
  const stateSet = new Set(Array.isArray(evidence?.states) ? evidence.states : [])
  for (const t of transitions) { if (t?.from) stateSet.add(t.from); if (t?.to) stateSet.add(t.to) }
  const states = [...stateSet].sort()
  if (states.length === 0) {
    return { id: 'lifecycle', kind: 'lifecycle', width: 420, height: 260, nodes: [], edges: [], spineIds: [], groups: [], meta: { stateCount: 0 } }
  }

  const spineIds = findLongestAcyclicSpine(states, transitions)
  const spineIndex = new Map(spineIds.map((s, i) => [s, i]))
  const offSpine = states.filter((s) => !spineIndex.has(s))
  const topArcTransitions = transitions.filter((t) => spineIndex.has(t.from) && spineIndex.has(t.to) && t.from !== t.to && spineIndex.get(t.to) !== spineIndex.get(t.from) + 1)
  const spineY = roundCoord(pad + Math.max(1, topArcTransitions.length) * arcStep + 26)
  const branchY = roundCoord(spineY + nodeH + branchGapY)

  const nodes = [], boxMap = new Map()
  spineIds.forEach((s, idx) => {
    const x = roundCoord(pad + idx * (nodeW + gapX))
    const box = { id: s, label: s, shortLabel: truncateLabel(s, 16), onSpine: true, spineIndex: idx, x, y: spineY, w: nodeW, h: nodeH, cx: roundCoord(x + nodeW / 2), cy: roundCoord(spineY + nodeH / 2) }
    nodes.push(box); boxMap.set(s, box)
  })
  const maxOffCols = Math.max(4, Math.min(6, spineIds.length || 5))
  const offRowGap = 44
  offSpine.forEach((s, idx) => {
    const col = idx % maxOffCols, row = Math.floor(idx / maxOffCols)
    const x = roundCoord(pad + col * (nodeW + gapX))
    const y = roundCoord(branchY + row * (nodeH + offRowGap))
    const box = { id: s, label: s, shortLabel: truncateLabel(s, 16), onSpine: false, spineIndex: -1, x, y, w: nodeW, h: nodeH, cx: roundCoord(x + nodeW / 2), cy: roundCoord(y + nodeH / 2) }
    nodes.push(box); boxMap.set(s, box)
  })

  const topPortUsage = new Map(), topPortPools = new Map(), topPortCursor = new Map()
  for (const t of topArcTransitions) {
    topPortUsage.set(t.from, (topPortUsage.get(t.from) || 0) + 1)
    topPortUsage.set(t.to, (topPortUsage.get(t.to) || 0) + 1)
  }
  for (const [id, cnt] of topPortUsage.entries()) topPortPools.set(id, spreadSidePorts(boxMap.get(id), 'top', cnt, 16))
  const takeTopPort = (id) => {
    const idx = topPortCursor.get(id) || 0
    topPortCursor.set(id, idx + 1)
    return (topPortPools.get(id) || [])[idx] || { x: boxMap.get(id).cx, y: boxMap.get(id).y, side: 'top' }
  }

  const edges = [], branchEdgeInputs = []
  let arcLane = 0
  transitions.forEach((t, idx) => {
    const src = boxMap.get(t.from), dst = boxMap.get(t.to)
    if (!src || !dst || src.id === dst.id) return
    const label = truncateLabel(String(t.label || t.event || `${t.from}->${t.to}`), 20)
    if (src.onSpine && dst.onSpine && dst.spineIndex === src.spineIndex + 1) {
      const pts = normalizeOrthogonalPoints([{ x: roundCoord(src.x + src.w), y: src.cy }, { x: dst.x, y: dst.cy }])
      edges.push({ id: `lc:${src.id}->${dst.id}:${idx}`, fromId: src.id, toId: dst.id, label, isTopArc: false, isRollback: false, points: pts, pathD: roundedOrthogonalPath(pts, 8), labelX: roundCoord((src.x + src.w + dst.x) / 2), labelY: roundCoord(src.cy - 10) })
    } else if (src.onSpine && dst.onSpine) {
      arcLane += 1
      const p1 = takeTopPort(src.id), p2 = takeTopPort(dst.id), archY = roundCoord(spineY - arcLane * arcStep)
      const pts = normalizeOrthogonalPoints([p1, { x: p1.x, y: archY }, { x: p2.x, y: archY }, p2])
      edges.push({ id: `lc:${src.id}->${dst.id}:${idx}`, fromId: src.id, toId: dst.id, label, isTopArc: true, isRollback: dst.spineIndex < src.spineIndex, points: pts, pathD: roundedOrthogonalPath(pts, 10), labelX: roundCoord((p1.x + p2.x) / 2), labelY: roundCoord(archY - 8) })
    } else {
      branchEdgeInputs.push({ id: `lc:${src.id}->${dst.id}:${idx}`, fromId: src.id, toId: dst.id, label, isTopArc: false, isRollback: false })
    }
  })

  if (branchEdgeInputs.length > 0) {
    for (const e of routeEdgesOrthogonal(branchEdgeInputs, boxMap, nodes, { clearance: 14, pad: 14 }).edges) {
      const mid = e.points[Math.floor(e.points.length / 2)] || e.points[0]
      e.labelX = roundCoord(mid?.x ?? 0); e.labelY = roundCoord((mid?.y ?? 0) - 8)
      edges.push(e)
    }
  }
  const dims = expandLayoutBounds(nodes, edges, [], pad, 460)
  return { id: 'lifecycle', kind: 'lifecycle', width: dims.width, height: dims.height, nodes, edges, spineIds, groups: [], meta: { stateCount: nodes.length, topArcCount: arcLane } }
}

/** Dataflow 阶段管道流布局：按 needs 拓扑分层生成分阶段通道列与避障路由边。 */
export function layoutDataflowDiagram(evidence, {
  nodeW = 196, nodeH = 56, colGap = 72, rowGap = 24, colPadX = 18, colHeadH = 38, colPadBottom = 18, pad = 36,
} = {}) {
  const rawStages = Array.isArray(evidence?.stages) ? evidence.stages : []
  const rawEdges = Array.isArray(evidence?.edges) ? evidence.edges : []
  const stageMap = new Map()
  for (const s of rawStages) {
    const id = String(s?.id || '').trim()
    if (id) stageMap.set(id, { id, label: String(s.label || (id.includes(':') ? id.split(':').pop() : id)), source: String(s.source || ''), kind: String(s.kind || 'stage') })
  }
  for (const e of rawEdges) {
    if (e?.from && !stageMap.has(e.from)) stageMap.set(e.from, { id: e.from, label: e.from.split(':').pop(), source: '', kind: 'stage' })
    if (e?.to && !stageMap.has(e.to)) stageMap.set(e.to, { id: e.to, label: e.to.split(':').pop(), source: '', kind: 'stage' })
  }
  const ids = [...stageMap.keys()].sort()
  if (ids.length === 0) {
    return { id: 'dataflow', kind: 'dataflow', width: 420, height: 260, nodes: [], edges: [], groups: [], meta: { stageCount: 0 } }
  }

  const pairs = rawEdges.filter((e) => stageMap.has(e.from) && stageMap.has(e.to) && e.from !== e.to).map((e) => [e.from, e.to])
  const { rank } = kahnTopoSort(ids, pairs, (a, b) => a.localeCompare(b))
  const byCol = new Map()
  for (const id of ids) {
    const r = rank.get(id) || 0
    if (!byCol.has(r)) byCol.set(r, [])
    byCol.get(r).push(stageMap.get(id))
  }
  const cols = [...byCol.keys()].sort((a, b) => a - b)
  const maxStack = Math.max(1, ...cols.map((c) => byCol.get(c).length))
  const colW = nodeW + colPadX * 2, colH = colHeadH + maxStack * nodeH + Math.max(0, maxStack - 1) * rowGap + colPadBottom

  const groups = [], nodes = [], boxMap = new Map()
  cols.forEach((c, idx) => {
    const gx = roundCoord(pad + idx * (colW + colGap)), gy = pad
    groups.push({ id: `stage-col-${idx}`, title: `阶段 ${idx + 1}`, isContainer: true, x: gx, y: gy, w: colW, h: colH })
    byCol.get(c).sort((a, b) => a.id.localeCompare(b.id)).forEach((item, rIdx) => {
      const nx = roundCoord(gx + colPadX), ny = roundCoord(gy + colHeadH + rIdx * (nodeH + rowGap))
      const node = { ...item, shortLabel: truncateLabel(item.label, 22), stageIndex: idx, x: nx, y: ny, w: nodeW, h: nodeH, cx: roundCoord(nx + nodeW / 2), cy: roundCoord(ny + nodeH / 2) }
      nodes.push(node); boxMap.set(node.id, node)
    })
  })

  const edgeInputs = rawEdges.filter((e) => boxMap.has(e.from) && boxMap.has(e.to) && e.from !== e.to).map((e, idx) => ({ id: `df:${e.from}->${e.to}:${idx}`, fromId: e.from, toId: e.to, label: String(e.label || '') }))
  const { edges } = routeEdgesOrthogonal(edgeInputs, boxMap, nodes, { clearance: 14, pad: 14 })
  const dims = expandLayoutBounds(nodes, edges, groups, pad, 460)
  return { id: 'dataflow', kind: 'dataflow', width: dims.width, height: dims.height, nodes, edges, groups, meta: { stageCount: nodes.length, columnCount: cols.length } }
}

function medianPositive(values) {
  const pos = values.filter((v) => Number.isFinite(v) && v > 0).sort((a, b) => a - b)
  if (pos.length === 0) return 0
  const mid = Math.floor(pos.length / 2)
  return pos.length % 2 === 1 ? pos[mid] : (pos[mid - 1] + pos[mid]) / 2
}

/** Timeline 演进时间线布局：当相邻间隔超过中位间隔 4x 时自动压缩并插入视觉断口标记。 */
export function layoutTimelineDiagram(evidence, {
  cardW = 168, cardH = 62, minStepX = 112, maxStepX = 210, compressedGapX = 136, stemH = 26, pad = 44,
} = {}) {
  const rawEvents = Array.isArray(evidence?.events) ? evidence.events : []
  if (rawEvents.length === 0) {
    return { id: 'timeline', kind: 'timeline', width: 420, height: 260, nodes: [], edges: [], axis: null, quietBreaks: [], groups: [], meta: { eventCount: 0 } }
  }

  const events = rawEvents.map((ev, idx) => {
    const ts = ev?.date ? Date.parse(String(ev.date)) : NaN
    const rawLbl = String(ev?.label || ev?.id || `event ${idx + 1}`).trim()
    const cleanLbl = rawLbl.replace(/^Merge pull request #(\d+) from [^/]+\/(?:feat\/|fix\/|chore\/|docs\/)?(.+)$/i, 'PR #$1 $2')
    return { id: String(ev?.id || `ev-${idx + 1}`), kind: String(ev?.kind || 'event'), date: String(ev?.date || ''), ts: Number.isFinite(ts) ? ts : null, sha: String(ev?.sha || ''), label: cleanLbl }
  }).sort((a, b) => ((a.ts !== null && b.ts !== null && a.ts !== b.ts) ? a.ts - b.ts : (a.date.localeCompare(b.date) || a.id.localeCompare(b.id))))

  const rawDeltas = []
  for (let i = 1; i < events.length; i += 1) rawDeltas.push(events[i].ts !== null && events[i - 1].ts !== null ? Math.max(0, events[i].ts - events[i - 1].ts) : 0)
  const medDelta = medianPositive(rawDeltas)

  const axisY = roundCoord(pad + cardH + stemH + 16), quietBreaks = [], anchorXs = [roundCoord(pad + cardW / 2)]
  for (let i = 1; i < events.length; i += 1) {
    const delta = rawDeltas[i - 1], prevX = anchorXs[i - 1]
    const isQuietGap = medDelta > 0 && delta > medDelta * QUIET_GAP_RATIO
    let step
    if (isQuietGap) {
      step = Math.max(minStepX, compressedGapX)
      const days = Math.round(delta / 86400000)
      quietBreaks.push({ index: i - 1, afterEventId: events[i - 1].id, beforeEventId: events[i].id, rawGapMs: delta, ratio: roundCoord(delta / medDelta), x: roundCoord(prevX + step / 2), y: axisY, label: days >= 1 ? `省略 ${days} 天静默期` : '静默压缩断口' })
    } else if (medDelta > 0 && delta > 0) {
      step = roundCoord(Math.max(minStepX, Math.min(maxStepX, minStepX + ((delta / (medDelta * QUIET_GAP_RATIO)) * (maxStepX - minStepX)))))
    } else {
      step = minStepX
    }
    anchorXs.push(roundCoord(prevX + step))
  }

  const lastRightBySide = { top: -Infinity, bottom: -Infinity }, nodes = [], edges = []
  events.forEach((ev, idx) => {
    const side = idx % 2 === 0 ? 'top' : 'bottom'
    let ax = anchorXs[idx]
    const desiredLeft = roundCoord(ax - cardW / 2)
    if (desiredLeft < lastRightBySide[side] + 16) {
      const shift = roundCoord(lastRightBySide[side] + 16 - desiredLeft)
      for (let k = idx; k < anchorXs.length; k += 1) anchorXs[k] = roundCoord(anchorXs[k] + shift)
      for (const qb of quietBreaks) if (qb.index >= idx - 1) qb.x = roundCoord((anchorXs[qb.index] + anchorXs[qb.index + 1]) / 2)
      ax = anchorXs[idx]
    }
    const x = roundCoord(ax - cardW / 2), y = side === 'top' ? roundCoord(axisY - stemH - cardH) : roundCoord(axisY + stemH)
    lastRightBySide[side] = x + cardW
    nodes.push({ id: ev.id, kind: ev.kind, date: ev.date, sha: ev.sha, label: ev.label, shortLabel: truncateLabel(ev.label, 20), side, anchorX: ax, anchorY: axisY, x, y, w: cardW, h: cardH, cx: roundCoord(x + cardW / 2), cy: roundCoord(y + cardH / 2) })
    const stemPts = normalizeOrthogonalPoints([{ x: ax, y: side === 'top' ? roundCoord(y + cardH) : y }, { x: ax, y: axisY }])
    edges.push({ id: `tl-stem:${ev.id}`, fromId: ev.id, toId: `axis:${ev.id}`, points: stemPts, pathD: roundedOrthogonalPath(stemPts, 4) })
  })

  const axis = { x1: roundCoord(Math.max(pad, anchorXs[0] - 24)), x2: roundCoord(anchorXs[anchorXs.length - 1] + 24), y: axisY }
  const dims = expandLayoutBounds(nodes, edges, [], pad, 460)
  return { id: 'timeline', kind: 'timeline', width: Math.max(dims.width, roundCoord(axis.x2 + pad)), height: dims.height, nodes, edges, axis, quietBreaks, groups: [], meta: { eventCount: nodes.length, quietBreakCount: quietBreaks.length } }
}

/** Waterfall 实测耗时甘特条布局：仅消费真实非负有限 telemetrySpans，绝不伪造耗时。 */
export function layoutWaterfallDiagram(evidence, {
  labelColW = 180, trackW = 480, rowH = 34, rowGap = 12, headH = 40, pad = 32,
} = {}) {
  const valid = []
  for (const sp of Array.isArray(evidence?.spans) ? evidence.spans : []) {
    if (!sp || typeof sp !== 'object') continue
    const id = String(sp.id ?? '').trim(), label = String(sp.label ?? '').trim()
    const startMs = Number(sp.startMs), durationMs = Number(sp.durationMs)
    if (!id || !label || !Number.isFinite(startMs) || startMs < 0 || !Number.isFinite(durationMs) || durationMs < 0) continue
    valid.push({ id, label, startMs, durationMs, endMs: roundCoord(startMs + durationMs), depth: Math.max(0, Math.floor(Number(sp.depth) || 0)) })
  }
  if (valid.length === 0) {
    return { id: 'waterfall', kind: 'waterfall', width: 420, height: 220, nodes: [], edges: [], ticks: [], totalMs: 0, groups: [], meta: { spanCount: 0 } }
  }

  const totalMs = Math.max(1, ...valid.map((s) => s.endMs)), trackX = pad + labelColW + 16
  const nodes = valid.map((sp, idx) => {
    const y = roundCoord(pad + headH + idx * (rowH + rowGap))
    const barX = roundCoord(Math.min(trackX + trackW - 4, trackX + (sp.startMs / totalMs) * trackW))
    const barW = roundCoord(Math.min(trackX + trackW - barX, Math.max(4, (sp.durationMs / totalMs) * trackW)))
    return {
      id: sp.id, label: sp.label, shortLabel: truncateLabel(sp.label, 20),
      startMs: sp.startMs, durationMs: sp.durationMs, endMs: sp.endMs, depth: sp.depth,
      labelX: roundCoord(pad + sp.depth * 12), labelW: roundCoord(Math.max(60, labelColW - sp.depth * 12)),
      barX, barW, x: barX, y, w: barW, h: rowH, cx: roundCoord(barX + barW / 2), cy: roundCoord(y + rowH / 2),
    }
  })
  const ticks = Array.from({ length: 5 }, (_, i) => {
    const ratio = i / 4, ms = roundCoord(totalMs * ratio)
    return { ms, label: `${ms}ms`, x: roundCoord(trackX + ratio * trackW) }
  })
  return {
    id: 'waterfall', kind: 'waterfall',
    width: roundCoord(trackX + trackW + pad),
    height: roundCoord(pad + headH + valid.length * rowH + Math.max(0, valid.length - 1) * rowGap + pad),
    nodes, edges: [], ticks, totalMs, groups: [], meta: { spanCount: nodes.length },
  }
}
